func NumericConstraintToEnvVar(v *NumericConstraint) map[string]string {
	if v == nil {
		return nil
	}
	result := make(map[string]string)
	if v.Gt != nil {
		result["PROTO_LIBS_SPEC_NUMERIC_CONSTRAINT_GT"] = strconv.FormatInt(*v.Gt, 10)
	}
	if v.Ge != nil {
		result["PROTO_LIBS_SPEC_NUMERIC_CONSTRAINT_GE"] = strconv.FormatInt(*v.Ge, 10)
	}
	if v.Lt != nil {
		result["PROTO_LIBS_SPEC_NUMERIC_CONSTRAINT_LT"] = strconv.FormatInt(*v.Lt, 10)
	}
	if v.Le != nil {
		result["PROTO_LIBS_SPEC_NUMERIC_CONSTRAINT_LE"] = strconv.FormatInt(*v.Le, 10)
	}
	if v.Eq != nil {
		result["PROTO_LIBS_SPEC_NUMERIC_CONSTRAINT_EQ"] = strconv.FormatInt(*v.Eq, 10)
	}
	if v.Ne != nil {
		result["PROTO_LIBS_SPEC_NUMERIC_CONSTRAINT_NE"] = strconv.FormatInt(*v.Ne, 10)
	}
	if len(v.In) > 0 {
		parts := make([]string, len(v.In))
		for i, val := range v.In {
			parts[i] = strconv.FormatInt(val, 10)
		}
		result["PROTO_LIBS_SPEC_NUMERIC_CONSTRAINT_IN"] = strings.Join(parts, ",")
	}
	if len(v.NotIn) > 0 {
		parts := make([]string, len(v.NotIn))
		for i, val := range v.NotIn {
			parts[i] = strconv.FormatInt(val, 10)
		}
		result["PROTO_LIBS_SPEC_NUMERIC_CONSTRAINT_NOT_IN"] = strings.Join(parts, ",")
	}
	if v.MultipleOf != nil {
		result["PROTO_LIBS_SPEC_NUMERIC_CONSTRAINT_MULTIPLE_OF"] = strconv.FormatInt(*v.MultipleOf, 10)
	}
	return result
}

